// SPDX-License-Identifier: Apache-2.0
// Per-version ABI tables.
//
// Each sub-module is generated by `gen/nvabi_gen.py` from gVisor's nvproxy and
// describes the frontend ioctls of one NVIDIA driver version. The backend
// selects a table at start-up from the host driver's own version
// (`/proc/driver/nvidia/version`; device/src/release.rs).
//
// The generated modules are kept exactly as the generator writes them, so
// rustfmt leaves them alone.

#[rustfmt::skip]
pub mod v535_129_03;
#[rustfmt::skip]
pub mod v580_178_04;
#[rustfmt::skip]
pub mod v595_71_05;

use crate::version::DriverVersion;

/// How the device must handle one escape.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum IoctlKind {
    /// Copy params in, call the host ioctl, copy params out. No handles, no
    /// mappings, no embedded pointers.
    Simple,
    /// Carries an embedded file descriptor that must be translated from a guest
    /// handle to a host fd before the host ioctl is issued.
    FdCarrying,
    /// Establishes a host mapping. The device allocates SHM and returns an
    /// offset; see `device/src/mmap.rs`.
    Mapping,
    /// `NV_ESC_RM_CONTROL`: nested dispatch on the embedded control command.
    RmControl,
    /// `NV_ESC_RM_ALLOC`: nested dispatch on the embedded allocation class.
    RmAlloc,
    /// `NV_ESC_RM_VID_HEAP_CONTROL`: a union whose active arm depends on the
    /// requested function.
    VidHeapControl,
    /// `NV_ESC_RM_IDLE_CHANNELS`: carries three guest pointer arrays.
    IdleChannels,
    /// A variable-length byte array with no fixed parameter struct, sized by
    /// the ioctl number at call time.
    Bytes,
}

/// One entry in a per-version ioctl table.
pub struct IoctlEntry {
    /// The `NV_ESC_*` escape, i.e. bits 7:0 of the Linux ioctl number.
    pub escape: u32,
    /// `sizeof` the parameter struct for this driver version, or `None` when
    /// the ioctl is variable length.
    pub param_size: Option<u32>,
    pub kind: IoctlKind,
}

/// A supported driver version and the table it selects.
struct Profile {
    version: DriverVersion,
    /// The first release the profile no longer describes, when that comes
    /// before the next profile: an escape's block changed there. `None`:
    /// it holds up to the next profile (or [`MEASURED_THROUGH`]).
    until: Option<DriverVersion>,
    table: fn() -> &'static [IoctlEntry],
}

/// Profiles in ascending version order.
static PROFILES: &[Profile] = &[
    // gVisor's nvproxy records the 535 branch unchanged through 535.309.01
    // and 545.23.06 unchanged from it; 550.40.07 grows UNMAP_MEMORY_DMA
    // to 48 bytes and adds WAIT_OPEN_COMPLETE, 570.86.15 grows
    // EXPORT_TO_DMABUF_FD, and 580.65.06 MAP_MEMORY_DMA.
    Profile {
        version: DriverVersion::new(535, 129, 3),
        until: Some(DriverVersion::new(550, 0, 0)),
        table: v535_129_03::table,
    },
    Profile {
        version: DriverVersion::new(580, 178, 4),
        until: None,
        table: v580_178_04::table,
    },
    Profile {
        version: DriverVersion::new(595, 71, 5),
        until: None,
        table: v595_71_05::table,
    },
];

/// The newest host release the last profile is known to describe.
///
/// Above it nothing has looked: a release NVIDIA publishes after it may move
/// an escape's block (580 did: NVOS46 grew to 64 bytes), and a profile that
/// silently stretched over it would size-check the guest against layouts
/// nobody measured. Evidence that the 595.71.05 profile holds up to here:
/// gVisor's nvproxy records no frontend change from 580.65.06 through
/// 620.30 (checked 2026-09-26); the A2000 capture at 615.71.09
/// (`fixtures/615.71.09.tsv`) matches it escape for escape; and every
/// release in `gen/rmallow` measured the RM escape blocks at the sizes it
/// states (`the_profiles_agree_with_every_measured_releases_escape_blocks`).
/// Moving this is part of measuring a new release (gen/README.md).
pub const MEASURED_THROUGH: DriverVersion = DriverVersion::new(615, 71, 9);

/// The profile for `v`, whether or not anything measured `v`.
fn profile_for(v: DriverVersion) -> Option<&'static Profile> {
    PROFILES.iter().rev().find(|p| p.version <= v)
}

/// Select the profile for `v`.
///
/// Profiles key off **ranges, not points**: a release between two known
/// versions selects the lower profile, which is what keeps the per-release cost
/// small -- but only up to the release its layouts are known to change at
/// (`Profile::until`). A version older than every profile has no table and
/// returns `None` -- guessing downwards would mean forwarding ioctls whose
/// layout we have never seen -- and so does one past its profile's range or
/// newer than [`MEASURED_THROUGH`], for the same reason upwards.
pub fn table_for(v: DriverVersion) -> Option<&'static [IoctlEntry]> {
    if v > MEASURED_THROUGH {
        return None;
    }
    profile_for(v)
        .filter(|p| p.until.is_none_or(|u| v < u))
        .map(|p| (p.table)())
}

/// The nearest profile at or below `v`, measured through `v` or not: what
/// `--allow-unmeasured-release` runs a newer host on. `None` only below
/// every profile.
pub fn nearest_table_for(v: DriverVersion) -> Option<&'static [IoctlEntry]> {
    profile_for(v).map(|p| (p.table)())
}

/// The version of the profile [`nearest_table_for`] picks, to name in a log.
pub fn nearest_profile_version(v: DriverVersion) -> Option<DriverVersion> {
    profile_for(v).map(|p| p.version)
}

/// Whether a driver version resolves to a table at all.
pub fn is_supported(v: DriverVersion) -> bool {
    table_for(v).is_some()
}

/// Look up one escape in a table.
pub fn lookup(table: &'static [IoctlEntry], escape: u32) -> Option<&'static IoctlEntry> {
    table.iter().find(|e| e.escape == escape)
}

/// The versions with a profile of their own, ascending.
pub fn supported_versions() -> impl Iterator<Item = DriverVersion> {
    PROFILES.iter().map(|p| p.version)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn exact_version_selects_its_own_profile() {
        let t = table_for(DriverVersion::new(580, 178, 4)).expect("580.178.04 has a profile");
        assert!(std::ptr::eq(t, v580_178_04::table()));
    }

    #[test]
    fn version_between_profiles_selects_the_lower_one() {
        // Later 535 releases, and 545, have 535.129.03's blocks.
        for v in [
            DriverVersion::new(535, 309, 1),
            DriverVersion::new(545, 23, 6),
        ] {
            let t = table_for(v).expect("falls back to 535");
            assert!(std::ptr::eq(t, v535_129_03::table()), "{v}");
        }
        // Between 580.178.04 and 595.71.05 nothing changed either.
        let t = table_for(DriverVersion::new(590, 48, 1)).expect("falls back to 580");
        assert!(std::ptr::eq(t, v580_178_04::table()));
    }

    /// From 550 on the 535 profile's blocks are not the host's: those
    /// releases have no measured profile, only a nearest one, and the
    /// start-up summary says so (device/src/release.rs `Coverage`).
    #[test]
    fn a_version_past_its_profiles_range_has_no_table_but_a_nearest_one() {
        for v in [
            DriverVersion::new(550, 40, 7),
            DriverVersion::new(570, 195, 3),
            DriverVersion::new(580, 126, 9),
        ] {
            assert!(table_for(v).is_none(), "{v}");
            assert!(!is_supported(v));
            let t = nearest_table_for(v).expect("the 535 profile");
            assert!(std::ptr::eq(t, v535_129_03::table()), "{v}");
        }
    }

    #[test]
    fn a_version_up_to_the_newest_measured_selects_the_highest_profile() {
        // The rig's host, one between, and the newest release measured.
        for v in [
            DriverVersion::new(595, 99, 2),
            DriverVersion::new(610, 43, 2),
            MEASURED_THROUGH,
        ] {
            let t = table_for(v).expect("falls back to 595");
            assert!(std::ptr::eq(t, v595_71_05::table()), "{v}");
        }
    }

    #[test]
    fn a_version_above_the_newest_measured_has_no_table_but_a_nearest_one() {
        for v in [
            DriverVersion::new(615, 71, 10),
            DriverVersion::new(620, 30, 0),
        ] {
            assert!(table_for(v).is_none(), "{v}");
            assert!(!is_supported(v));
            let t = nearest_table_for(v).expect("the newest profile");
            assert!(std::ptr::eq(t, v595_71_05::table()));
            assert_eq!(
                nearest_profile_version(v),
                Some(DriverVersion::new(595, 71, 5))
            );
        }
        assert!(nearest_table_for(DriverVersion::new(470, 0, 0)).is_none());
    }

    /// Every release `gen/rmallow` measured from NVIDIA's sources has a
    /// profile, and the profile's sizes for the RM escapes are the block
    /// sizes measured there.
    #[test]
    fn the_profiles_agree_with_every_measured_releases_escape_blocks() {
        use crate::ioctl::*;
        use crate::rmallow;
        for r in rmallow::RELEASES {
            let v = r.version();
            assert!(
                v <= MEASURED_THROUGH,
                "{v} measured but past MEASURED_THROUGH"
            );
            let t = table_for(v).unwrap_or_else(|| panic!("{v}: no profile"));
            for (escape, size) in [
                (NV_ESC_RM_CONTROL, rmallow::nvos::NVOS54_SIZE),
                (NV_ESC_RM_ALLOC, rmallow::nvos::NVOS64_SIZE),
                (NV_ESC_RM_VID_HEAP_CONTROL, rmallow::nvos::NVOS32_SIZE),
                (NV_ESC_RM_ALLOC_CONTEXT_DMA2, rmallow::nvos::NVOS39_SIZE),
            ] {
                let e = lookup(t, escape).unwrap_or_else(|| panic!("{v}: {escape:#x}"));
                assert_eq!(e.param_size, Some(size as u32), "{v}: {escape:#x}");
            }
        }
    }

    #[test]
    fn version_below_every_profile_is_unsupported() {
        assert!(table_for(DriverVersion::new(470, 0, 0)).is_none());
        assert!(!is_supported(DriverVersion::new(470, 0, 0)));
    }

    #[test]
    fn profiles_are_sorted_ascending() {
        let vs: Vec<_> = supported_versions().collect();
        let mut sorted = vs.clone();
        sorted.sort();
        assert_eq!(vs, sorted, "PROFILES must stay in ascending order");
    }
}
